mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.MTNG_DY DESC) AS LISTNUM, UNQ_KY_VAL, DIVS_CD, PPCD, (SELECT PWPL_NM FROM GE_MP_PWPL_C WHERE PPCD = A.PPCD) AS PPCD_NM, FRM_CFY, CASE WHEN A.FRM_CFY = 'GEN' THEN '일반작업전회의' WHEN A.FRM_CFY = 'REP' THEN '정비작업전회의' WHEN A.FRM_CFY = 'MAN_GEN' THEN '수기등록(일반)' WHEN A.FRM_CFY = 'MAN_REP' THEN '수기등록(정비)' ELSE '' END AS FRM_CFY_NM, (SELECT FRM_NM FROM GE_MP_ETCFRM_M WHERE FRM_UNQ_KY_VAL = A.FRM_UNQ_KY_VAL) AS FRM_NM, PRCDOC_NO, PRCDOC_VER_NO, MTNG_DY, REGEXP_REPLACE(MTNG_DY, '(.{4})(.{2})(.{2})','\1-\2-\3') AS FM_MTNG_DY, MTNG_HSMPR_ID, MTNG_TITL, MTNG_PLC_NM, WRK_SCTN_NM, WRK_NM, WRK_TRGT_NM, WRKOR_NO, REGPR_ID, REGPR_NM, RG_DT, TO_CHAR(RG_DT, 'YYYY-MM-DD') AS FM_RG_DT, (SELECT ATFL_GRUP_NM||'/'||ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM = 'GE_MP_JOB_S' AND UNQ_NO = A.UNQ_KY_VAL) AS ATFL_PHCL_NM, (SELECT ATFL_GRUP_NM||'/'||ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM = 'GE_MP_ETCFRM_M' AND UNQ_NO = '1') AS ATFL_PHCL_NM_GEN, (SELECT ATFL_GRUP_NM||'/'||ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM = 'GE_MP_ETCFRM_M' AND UNQ_NO = '2') AS ATFL_PHCL_NM_REP, A.TRSN_YN, CASE WHEN A.TRSN_YN = 'N' THEN '미전송' WHEN A.TRSN_YN = 'Y' THEN '전송' ELSE '' END AS TRSN_YN_NM FROM GE_MP_JOB_S A WHERE 1 = 1
AND A.PPCD = #{PPCD}
AND A.FRM_CFY = #{FRM_CFY}
AND A.FRM_NM LIKE '%'||#{FRM_NM}||'%'
AND A.WRK_NM LIKE '%'||#{WRK_NM}||'%'
AND A.REGPR_NM LIKE '%'||#{REGPR_NM}||'%'
AND A.MTNG_DY BETWEEN #{MTNG_DY_S} AND #{MTNG_DY_E} ORDER BY MTNG_DY DESC ) WHERE LISTNUM BETWEEN #{DISPSTART} AND #{DISPEND}

mapper.update:
UPDATE GE_MP_JOB_S
   SET RG_DT = SYSDATE
WHERE UNQ_KY_VAL = #{UNQ_KY_VAL}

UPDATE GE_MP_JOB_S
   SET TRSN_YN = 'Y'
WHERE UNQ_KY_VAL = #{UNQ_KY_VAL}

UPDATE GE_MP_JOB_S
   SET RG_DT = SYSDATE
WHERE UNQ_KY_VAL = #{UNQ_KY_VAL}
